-- 096_colombia_public_cities_divipola.sql
-- warocol.com#1477 - Complete Colombia municipality catalog for /negocio.
--
-- Source: DANE/Datos Abiertos DIVIPOLA dataset gdxc-w37w
-- https://www.datos.gov.co/resource/gdxc-w37w.json
-- Generated from rows where tipo_municipio = 'Municipio' (1103 rows on 2026-06-27).
-- Non-municipalized areas and island rows are intentionally out of scope for this batch.
--
-- Slug policy:
-- - Existing public slugs from migration 076 are preserved for route stability.
-- - Municipality names that collide across departments append the department slug.
-- - DIVIPOLA municipality_code is stored as the stable source identifier.

ALTER TABLE public_cities
    ADD COLUMN IF NOT EXISTS department_code VARCHAR(2),
    ADD COLUMN IF NOT EXISTS department_name VARCHAR(120),
    ADD COLUMN IF NOT EXISTS municipality_code VARCHAR(5),
    ADD COLUMN IF NOT EXISTS municipality_type VARCHAR(80),
    ADD COLUMN IF NOT EXISTS latitude NUMERIC(10,6),
    ADD COLUMN IF NOT EXISTS longitude NUMERIC(10,6);

COMMENT ON COLUMN public_cities.department_code IS
    'DANE/DIVIPOLA department code from Datos Abiertos dataset gdxc-w37w (warocol.com#1477).';
COMMENT ON COLUMN public_cities.department_name IS
    'Department display name from DANE/DIVIPOLA dataset gdxc-w37w (warocol.com#1477).';
COMMENT ON COLUMN public_cities.municipality_code IS
    'DANE/DIVIPOLA municipality code from Datos Abiertos dataset gdxc-w37w (warocol.com#1477).';
COMMENT ON COLUMN public_cities.municipality_type IS
    'DANE/DIVIPOLA municipality type; this migration imports only Municipio rows (warocol.com#1477).';
COMMENT ON COLUMN public_cities.latitude IS
    'Latitude from DANE/DIVIPOLA dataset gdxc-w37w, normalized from decimal comma (warocol.com#1477).';
COMMENT ON COLUMN public_cities.longitude IS
    'Longitude from DANE/DIVIPOLA dataset gdxc-w37w, normalized from decimal comma (warocol.com#1477).';

CREATE UNIQUE INDEX IF NOT EXISTS idx_public_cities_municipality_code
    ON public_cities(municipality_code)
    WHERE municipality_code IS NOT NULL;

