INSERT INTO public_cities (
    country,
    city,
    city_slug,
    sort_order,
    department_code,
    department_name,
    municipality_code,
    municipality_type,
    latitude,
    longitude
)
SELECT
    country,
    city,
    city_slug,
    sort_order,
    department_code,
    department_name,
    municipality_code,
    municipality_type,
    latitude,
    longitude
FROM divipola_municipalities
ON CONFLICT (city_slug) DO UPDATE
SET
    country = EXCLUDED.country,
    city = CASE
        WHEN public_cities.city_slug IN ('barranquilla', 'bogota', 'bucaramanga', 'cali', 'cartagena', 'manizales', 'medellin', 'mosquera', 'pereira', 'santa-fe-de-antioquia') THEN public_cities.city
        ELSE EXCLUDED.city
    END,
    sort_order = public_cities.sort_order,
    department_code = EXCLUDED.department_code,
    department_name = EXCLUDED.department_name,
    municipality_code = EXCLUDED.municipality_code,
    municipality_type = EXCLUDED.municipality_type,
    latitude = EXCLUDED.latitude,
    longitude = EXCLUDED.longitude;
